                if not line:
                    break  # EOF
                line = line.strip()
                if not line:
                    continue
                self.handle_command(line)
            except KeyboardInterrupt:
                continue
            except Exception as e:
                sys.__stderr__.write(f"Fatal error in main loop: {e}\n")
                break


if __name__ == "__main__":
